# One mapped Conv2d followed by timing-only MaxPool2d and AvgPool2d (SFU-executed;
# pool operations take no MAC mapping). Captured with REAL torch.export (see
# pool_chain_graph.json metadata) -- op_ids are the exported node names.
# Conv full coverage: K=8, P=8, Q=8, C=3, R=S=3 -> 13,824 MACs.
[convolutional]
op_id  = conv2d
MAC     = 1, 1, 1, 1, 1, 1, 1, 0, 0, 1, 1,
PE      = 1, 1, 1, 1, 1, 3, 3, 0, 0, 1, 1,
PE_X    = 8, 1, 1, 1, 1, 1, 1, 0, 0, 1, 1,
PE_Y    = 1, 1, 1, 1, 3, 1, 1, 0, 0, 1, 1,
GLB     = 1, 1, 8, 8, 1, 1, 1, 0, 0, 1, 1,
CHIPS_X = 1, 1, 1, 1, 1, 1, 1, 0, 0, 1, 1,
CHIPS_Y = 1, 1, 1, 1, 1, 1, 1, 0, 0, 1, 1,
DRAM    = 1, 1, 1, 1, 1, 1, 1, 0, 0, 1, 1,
